						long: "However, these talents are second nature and completely natural. So, for example, if a man has Venus trine Neptune, he may be poetic, romantic, or artistic, and he may easily accept his romantic partner for who he/she is. Another man with Venus square Neptune may have similar qualities and may possess a strong desire to accept his partner blindly, but doing so is not as natural as the first man. He has to work on it and might come up against difficult situations in which he feels duped or abused by his partners as a result of that acceptance.",
