						short: "Planets in trine support each other. Trines, by nature, are accepting. They allow us to accept others, ourselves, and situations. The talents that trines offer a native are so natural that they are almost unconscious. Often enough, natives don't truly appreciate the talents these trines offer them, and they may not try to develop them.",
