				description: "The bottom right arrow, fed by the personality Nodes. Also called View, it describes the structure through which the mind is angled to see, framing what awareness notices before any thought forms.",
				layerDescription: "The mind-side half of Variable, covering the Perspective and Motivation arrows. It addresses awareness: how the mind is built to see and what colors that seeing, along with the false resonance of Distraction and Transference.",
				colorMeaning: "Probability. The mind weighs how a thing is most likely to unfold. This is not open-ended speculation but an estimate of the odds on something already taken as possible.",
				toneMeaning: "Uncertainty. An unease with things as they stand, which keeps awareness attuned to what is new. This is the tone that recognizes mutation the moment it appears, before it can be named.",
				directionMeaning: "Focused. Awareness narrows and aims, picking out what is central, specific, and sharply relevant, and leaving the surrounding field out of frame.",
