				layerDescription: "The mind-side half of Variable, covering the Perspective and Motivation arrows. It addresses awareness: how the mind is built to see and what colors that seeing, along with the false resonance of Distraction and Transference.",
				colorMeaning: "Innocence. Awareness is motivated by no agenda at all, meeting what arrives without gripping it. Life supplies the next thing, and influence comes by example rather than by push.",
