	hex: {
		number: 28,
		symbol: "䷛",
		chinese: "大過",
		english: "Preponderance of the Great",
		pinyin: "Dà Guò",
		binary: "011110",
		upperTrigram: "Lake",
		lowerTrigram: "Wind",
		judgment: "The load is stacked in the middle and the ends cannot carry it, so the ridgepole is bending. This is an extraordinary moment and it asks for extraordinary measures, so move, because standing still under a sagging beam is not caution.",
		image: "The lake has risen over the trees and drowns the wood that ought to stand above it. Stand alone without alarm when it comes to that, and withdraw from the world without bitterness if the time demands it.",
		interpretation: {
			general: "The situation has reached a critical point where the load is too heavy for the structure bearing it. Extraordinary measures are needed. The ridgepole is sagging. Act boldly but wisely. This is a time that calls for independence and decisive movement toward resolution.",
			love: "The relationship is under extraordinary pressure. Extraordinary measures may be needed. Do not expect normal rules to apply in exceptional circumstances.",
			career: "Exceptional times call for exceptional action. The structure is strained and requires decisive intervention. Act with courage when ordinary approaches fail.",
			decision: "The situation is extreme and demands unusual responses. Move with determination in whatever direction is necessary. Hesitation in crisis leads to collapse.",
			advice: "When the ridgepole sags, it must be reinforced or replaced. Extraordinary times require extraordinary measures. Stand alone if necessary, remain free of fear.",
		},
		changingLines: [
			{
				position: 1,
				text: "White grass is laid down as a mat beneath what is being set on the ground.",
				meaning: "The first line is yielding and at the bottom, carrying weight it was never built for. Excessive care at the base is not fussiness in a situation this loaded, it is the difference between holding and cracking. Everything above rests on this mat, so take the extra precaution.",
			},
			{
				position: 2,
				text: "The old willow puts out new shoots, and an aging man takes a young wife.",
				meaning: "The second line is strong and central, and it turns toward the yielding line beneath it rather than upward. The pairing is unconventional and it is fertile, which is the only test this hexagram applies. Under extraordinary strain, an unlikely renewal beats a respectable sterility.",
			},
			{
				position: 3,
				text: "The ridgepole bends, and it is going to break.",
				meaning: "Line three is the exposed threshold, strong, and standing alone with no real support behind it. It has decided it can carry the whole load by itself, which is precisely the error this hexagram names. Excess strength with no help is not strength, so refuse the weight or find someone to share it.",
			},
			{
				position: 4,
				text: "The ridgepole arches upward and holds, so long as no extra weight is invited onto it.",
				meaning: "The fourth line is strong but sits in a yielding place, so its force is tempered and it can bear what it has been given. It works because the strength is balanced, and reaching down for more support would unbalance it again. Hold what you have and add nothing.",
			},
			{
				position: 5,
				text: "The old willow puts out flowers, and an aging woman takes a young husband.",
				meaning: "The fifth place rules, and here a strong line reaches upward to the yielding line at the top for its renewal. Flowers on an old trunk are pretty and they set no fruit, so nothing continues from this. It is not a fault and it is not an achievement, and mistaking it for either is the actual error.",
			},
			{
				position: 6,
				text: "The crossing goes on until the water closes over the head.",
				meaning: "The top line is yielding, past the peak, and it takes on a burden nobody could have carried. The attempt fails and the failure is total, so call it what it is. But the motive was to save something larger than yourself, which is why there is misfortune here and still no blame.",
			},
		],
	},
